-- Figma 20 Nov replay exactly as run (generated by 05_gen_replay_sql.py from 04_replay_per_signature_template.sql).
WITH b0 AS (SELECT di_matched_signature_at_session_created ms, COUNT(*) c FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND session_last_timestamp>='2026-11-13 00:00' AND session_last_timestamp<'2026-11-21 06:00' AND session_ts>='2026-11-13 00:00' AND session_ts<'2026-11-20 00:00' AND COALESCE(latest_risk_band,'')<>'High' GROUP BY 1), sh AS (SELECT ms, c/SUM(c) OVER () share FROM b0), a0 AS (SELECT session sid, session_ts ts, di_dictionary_num_matched_at_session_created d, di_matched_signature_at_session_created ms, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, IFF(was_challenged>0,1,0) chl, IFF(was_challenged>0 AND COALESCE(sessions_solved,0)=0,1,0) chns, di_short_term_count_at_session_created stc, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb, TIME_SLICE(session_ts,20,'MINUTE') b20 FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='A207F8A1-ED09-4325-ACE6-C8E26A458FBA' AND session_last_timestamp>='2026-11-19 23:40' AND session_last_timestamp<'2026-11-21 06:00' AND session_ts>='2026-11-19 23:40' AND session_ts<'2026-11-21 00:00'), bc AS (SELECT b20, COUNT(*) bn FROM a0 GROUP BY 1), a1 AS (SELECT a0.*, COUNT(*) OVER (PARTITION BY a0.b20 ORDER BY ts, sid ROWS UNBOUNDED PRECEDING) + COALESCE(p.bn,0) vol FROM a0 LEFT JOIN bc p ON p.b20 = DATEADD(minute,-20,a0.b20)), s1 AS (SELECT a1.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp0, COALESCE(sh.share,0) share, CASE WHEN d IN (1,3) THEN 1 WHEN d=7 THEN 1.5 ELSE 2 END dfac FROM a1 LEFT JOIN sh ON sh.ms=a1.ms WHERE a1.ts>='2026-11-20 00:00' AND a1.d IS NOT NULL), s2 AS (SELECT s1.*, IFF(x IS NULL, grp0, 'SKIP_'||x) grp, IFF(x IS NULL AND ms IS NOT NULL AND d>0, 1, 0) elig, IFF(SUM(hi) OVER (PARTITION BY x, grp0, ms, TIME_SLICE(ts,40,'MINUTE')) / COUNT(*) OVER (PARTITION BY x, grp0, ms, TIME_SLICE(ts,40,'MINUTE')) < 0.2, 1, 0) cl, IFF(HOUR(ts) IN (12,13),1,0) sl , 0 lab FROM s1 ), gr(gp,m,f) AS (SELECT * FROM VALUES (1,2,5),(2,5,5),(3,10,5),(4,20,5),(5,2,11),(6,5,11),(7,10,11),(8,20,11),(0,0,0)), x AS (SELECT gp, d, grp, sl, hi, ver, chl, chns, cl, lab, stb, ltb, IFF(gp=0, stb, IFF(elig=1 AND stc > GREATEST(f, share*vol*m*dfac), 1, 0)) fi FROM s2 CROSS JOIN gr) SELECT gp||'|'||COALESCE(d::STRING,'ALL')||'|'||COALESCE(grp,'ALL')||'|'||COALESCE(sl::STRING,'ALL')||'|'||COUNT(*)||'|'||SUM(cl)||'|'||SUM(fi)||'|'||SUM(fi*hi)||'|'||SUM(fi*ver)||'|'||SUM(fi*chl)||'|'||SUM(fi*chns) ||'|'||SUM(fi*cl)||'|'||SUM(fi*(1-stb))||'|'||SUM(stb*(1-fi))||'|'||SUM(lab)||'|'||SUM(fi*lab)||'|'||SUM(ltb)||'|'||SUM(fi*cl*hi) r FROM x GROUP BY GROUPING SETS ((gp, d, grp), (gp, sl)) HAVING SUM(fi)+SUM(stb)>0 OR gp=0 ORDER BY gp, d, grp, sl;
